import type { ImageAsset } from "@/data/types";
import manifest from "@/data/image-manifest.json";

type ManifestEntry = {
  site_id: string; also_site_ids: string[]; hero: string | null; gallery: string[]; thumbnail: string | null;
  alt_en: string; source_url: string | null; photographer: string | null; license: string | null; verification_status: string;
};

/**
 * Photos from src/data/image-manifest.json (generated by `npm run photos:import`).
 * Only entries a human marked "verified" (correct place + licence checked) are returned;
 * "source_checked" and "placeholder" entries never reach the public site.
 */
const BY_SITE = new Map<string, ImageAsset[]>();
for (const m of manifest as ManifestEntry[]) {
  if (m.verification_status !== "verified" || !m.hero || !m.photographer || !m.license) continue;
  const asset = (url: string): ImageAsset => ({ url, alt: m.alt_en, credit: m.photographer!, license: m.license!, sourceUrl: m.source_url ?? "", verified: true });
  const images = [asset(m.hero), ...m.gallery.map(asset)];
  for (const slug of [m.site_id, ...m.also_site_ids]) if (!BY_SITE.has(slug)) BY_SITE.set(slug, images);
}

export function manifestPhotos(siteSlug: string): ImageAsset[] {
  return BY_SITE.get(siteSlug) ?? [];
}

export function governoratePhotos(govSlug: string): ImageAsset[] {
  return BY_SITE.get(`gov:${govSlug}`) ?? [];
}
